// TorqueDoc website offline cache (generated by website/build.py; do not edit dist/sw.js).
// Keeps the whole app, the built-in library and its PDFs on the device after the first visit.
const VERSION = '__VERSION__';
const CACHE = `torquedoc-web-${VERSION}`;
const FILES = __FILES__;

self.addEventListener('install', event => {
  event.waitUntil(caches.open(CACHE).then(cache => cache.addAll(FILES)));
});

self.addEventListener('activate', event => {
  event.waitUntil(caches.keys()
    .then(keys => Promise.all(keys.filter(key => key.startsWith('torquedoc-web-') && key !== CACHE).map(key => caches.delete(key))))
    .then(() => self.clients.claim()));
});

// Cross-origin isolation lets the experimental on-device AI use several processor cores on any host.
function isolated(response) {
  if (!response || response.status === 0 || response.type === 'opaque') return response;
  const headers = new Headers(response.headers);
  headers.set('Cross-Origin-Opener-Policy', 'same-origin');
  headers.set('Cross-Origin-Embedder-Policy', 'require-corp');
  headers.set('Cross-Origin-Resource-Policy', 'same-origin');
  return new Response(response.body, { status: response.status, statusText: response.statusText, headers });
}

self.addEventListener('fetch', event => {
  const request = event.request;
  const url = new URL(request.url);
  if (request.method !== 'GET' || url.origin !== self.location.origin) return;  // model downloads and links pass through
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    const cached = await cache.match(request, { ignoreSearch: true }) ||
      (request.mode === 'navigate' ? await cache.match('./', { ignoreSearch: true }) : undefined);
    if (cached) return isolated(cached);
    try {
      return isolated(await fetch(request));
    } catch {
      return new Response('TorqueDoc is offline and this file was not saved on the device.', { status: 503 });
    }
  })());
});
